// WF 24 v4 - Inspecionar 1 ticket especifico por ID
// ALTERE A VARIAVEL TICKET_ID_ALVO ABAIXO para o ID que voce quer inspecionar

const TICKET_ID_ALVO = 2025000186;  // <-- TROQUE pelo ID real (ex: 2025000186)

const helpers = this.helpers;
const baseV1 = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseV1}/initSession`, {
  'App-Token': appToken, 'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { erro: 'auth falhou', body: r0.body }}];
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

// 1) Buscar ticket diretamente
const tk = await callRaw('GET', `${baseV1}/Ticket/${TICKET_ID_ALVO}`, H);
const ticket = tk.body;

// 2) Buscar categoria pelo nome via search (forcedisplay 7)
const search = await callRaw('GET',
  `${baseV1}/search/Ticket?criteria[0][field]=2&criteria[0][searchtype]=equals&criteria[0][value]=${TICKET_ID_ALVO}&forcedisplay[0]=2&forcedisplay[1]=1&forcedisplay[2]=7&forcedisplay[3]=15&forcedisplay[4]=21&forcedisplay[5]=12&forcedisplay[6]=80`,
  H);

await callRaw('GET', `${baseV1}/killSession`, H);

return [{ json: {
  ticket_id: TICKET_ID_ALVO,
  ticket_status: tk.status,
  ticket_data: ticket,
  search_result: search.body,
  search_count: search.body && search.body.count,
  search_data: search.body && search.body.data ? search.body.data[0] : null,
  legenda_forcedisplay: {
    '2': 'id',
    '1': 'nome',
    '7': 'categoria (caminho completo)',
    '15': 'data_creation',
    '21': 'content (HTML)',
    '12': 'status',
    '80': 'entidade'
  }
}}];

